candidate.program:
def choose(n, r):
    for i in range(n):
        if r == 0:
            return i
        max_new = -1
        best = -1
        for j in range(n):
            if v(j, 4):  # archive flag
                continue
            new = pop(v(j, 2))
            if new > max_new:
                max_new = new
                best = j
        return best

